//! WPT `mimesniff/mime-types/`: the MIME type parsing cases, as a table of
//! (input string, expected serialization or failure).
//!
//! Both files are JSON arrays. A string element is a section heading; an
//! object has `input` and `output` (`null`: parsing fails), and in
//! `mime-types.json` also `navigable`, `encoding` and `minimizedMIMEType`,
//! which test HTML and Encoding behaviour, not MIME type parsing, and are
//! not converted. Any other shape fails the conversion.

use std::fmt::Write as _;
use std::path::Path;

use serde_json::Value;

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &["generated-mime-types.json", "mime-types.json"];

/// Keys an object may have; only `input` and `output` are converted.
const KEYS: &[&str] = &[
    "input",
    "output",
    "navigable",
    "encoding",
    "minimizedMIMEType",
];

fn scalars(s: &str) -> String {
    let items: Vec<String> = s
        .chars()
        .map(|c| format!("0x{:04X}", u32::from(c)))
        .collect();
    format!("&[{}]", items.join(", "))
}

fn quote(s: &str) -> String {
    format!("{s:?}")
}

pub fn convert(dir: &Path) -> Result<String, String> {
    let mut out = String::new();
    out.push_str(
        "// @generated by `cargo xtask testdata` from tests/data/wpt-mime-types/.\n\
         // Do not edit: `cargo xtask verify` fails if this differs from what the\n\
         // converter (xtask/src/testdata/wpt_mime_types.rs) produces.\n\
         // Source, commit and license: tests/data/wpt-mime-types/SOURCE.md.\n\
         const WPT: &[Case] = &[\n",
    );
    for file in FILES {
        let path = dir.join(file);
        let text =
            std::fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        let json: Value =
            serde_json::from_str(&text).map_err(|e| format!("{}: {e}", path.display()))?;
        let rows = json
            .as_array()
            .ok_or_else(|| format!("{file}: expected a JSON array"))?;
        let mut section = String::new();
        for (index, row) in rows.iter().enumerate() {
            if let Some(heading) = row.as_str() {
                heading.clone_into(&mut section);
                continue;
            }
            let obj = row
                .as_object()
                .ok_or_else(|| format!("{file}[{index}]: expected a string or an object"))?;
            if let Some(k) = obj.keys().find(|k| !KEYS.contains(&k.as_str())) {
                return Err(format!("{file}[{index}]: unexpected key {k:?}"));
            }
            let input = obj
                .get("input")
                .and_then(Value::as_str)
                .ok_or_else(|| format!("{file}[{index}]: no string \"input\""))?;
            let output = match obj.get("output") {
                Some(Value::Null) => "None".to_owned(),
                Some(Value::String(s)) => format!("Some({})", scalars(s)),
                _ => {
                    return Err(format!(
                        "{file}[{index}]: \"output\" is not a string or null"
                    ));
                }
            };
            writeln!(
                out,
                "    Case {{ file: {}, index: {index}, section: {}, input: {}, output: {output} }},",
                quote(file),
                quote(&section),
                scalars(input)
            )
            .map_err(|e| e.to_string())?;
        }
    }
    out.push_str("];\n");
    Ok(out)
}
